#!/usr/bin/env bash
# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: verify-observability-e2e.sh
NS=ibts-observability
OTEL=otel-collector-opentelemetry-collector
MARK="OBSSMOKE$(date +%s)"
FAILED=0

t(){ local d=$1; shift; if "$@" >/dev/null 2>&1; then echo "  [PASS] $d"; else echo "  [FAIL] $d"; FAILED=1; fi; }

kubectl create ns ibts-apps --dry-run=client -o yaml | kubectl apply -f - >/dev/null
JQ_PORT=$(kubectl get svc jaeger-query -n $NS -o jsonpath='{.spec.ports[0].port}')
kubectl port-forward svc/elasticsearch-master 9200:9200 -n $NS >/dev/null 2>&1 & P1=$!
kubectl port-forward svc/kube-prometheus-stack-prometheus 9090:9090 -n $NS >/dev/null 2>&1 & P2=$!
kubectl port-forward svc/jaeger-query 16686:${JQ_PORT} -n $NS >/dev/null 2>&1 & P3=$!
trap 'kubectl delete pod log-smoke -n ibts-apps --ignore-not-found >/dev/null 2>&1; kill $P1 $P2 $P3 2>/dev/null' EXIT
sleep 5

# ---------- checks ----------
no_pod_problems(){ [ "$(kubectl get pods -A --no-headers | grep -vcE 'Running|Completed')" -eq 0 ]; }
fluent_everywhere(){ [ "$(kubectl get ds fluent-bit -n $NS -o jsonpath='{.status.numberReady}')" = "$(kubectl get nodes --no-headers | wc -l)" ]; }
es_not_red(){ curl -s localhost:9200/_cluster/health | jq -e '.status=="green" or .status=="yellow"'; }
prom_no_down(){ [ "$(curl -s localhost:9090/api/v1/targets | jq '[.data.activeTargets[]|select(.health!="up")]|length')" -eq 0 ]; }
am_real_receiver(){
  kubectl get secret alertmanager-kube-prometheus-stack-alertmanager -n $NS \
    -o jsonpath='{.data.alertmanager\.yaml}' | base64 -d \
    | grep -E '^\s*-?\s*name:' | grep -viE 'null' | grep -q .
}
otel_has_4318(){ kubectl get svc $OTEL -n $NS -o jsonpath='{.spec.ports[*].port}' | grep -qw 4318; }
send_trace(){
  local NOW END TID SID BODY
  NOW=$(date +%s%N); END=$((NOW+500000000))
  TID=$(openssl rand -hex 16); SID=$(openssl rand -hex 8)
  BODY='{"resourceSpans":[{"resource":{"attributes":[{"key":"service.name","value":{"stringValue":"obs-smoke"}}]},"scopeSpans":[{"spans":[{"traceId":"'$TID'","spanId":"'$SID'","name":"smoke-span","kind":2,"startTimeUnixNano":"'$NOW'","endTimeUnixNano":"'$END'"}]}]}]}'
  kubectl run otlp-smoke -n $NS --rm -i --restart=Never --image=curlimages/curl -- \
    -sf -X POST "http://$OTEL.$NS.svc.cluster.local:4318/v1/traces" -H 'Content-Type: application/json' -d "$BODY"
}
jaeger_has_trace(){ for i in $(seq 1 12); do curl -s "localhost:16686/api/traces?service=obs-smoke&limit=1" | jq -e '.data|length>0' && return 0; sleep 5; done; return 1; }
start_log_pod(){ kubectl run log-smoke -n ibts-apps --image=busybox:1.36 --restart=Never -- sh -c "for i in \$(seq 1 60); do echo $MARK; sleep 3; done"; }
es_has_log(){ for i in $(seq 1 24); do curl -s "localhost:9200/_search?q=$MARK&size=1" | jq -e '.hits.total.value>0' && return 0; sleep 5; done; return 1; }
es_log_has_k8s_meta(){ curl -s "localhost:9200/_search?q=$MARK&size=1" | jq -e '.hits.hits[0]._source|tostring|contains("ibts-apps")'; }
redis_up(){ curl -s 'localhost:9090/api/v1/query?query=redis_up' | jq -e '.data.result[0].value[1]=="1"'; }
prom_container(){ curl -s -G localhost:9090/api/v1/query --data-urlencode 'query=container_memory_working_set_bytes{namespace="ibts-apps"}' | jq -e '.data.result|length>0'; }

# ---------- run ----------
echo "== Start log pod first (gives Fluent Bit time) =="
t "Test log pod started" start_log_pod

echo "== Platform =="
t "No pods outside Running/Completed"      no_pod_problems
t "Fluent Bit runs on every node"          fluent_everywhere
t "Elasticsearch green/yellow"             es_not_red
t "Alertmanager has a non-null receiver"   am_real_receiver

echo "== Traces (same path the apps use: OTLP HTTP :4318) =="
t "OTel service exposes 4318"              otel_has_4318
t "OTLP/HTTP trace accepted by collector"  send_trace
t "Trace arrived in Jaeger (obs-smoke)"    jaeger_has_trace

echo "== Logs (pod in ibts-apps -> Fluent Bit -> ES) =="
t "Marker $MARK indexed in ES"             es_has_log
t "Log carries ibts-apps k8s metadata"     es_log_has_k8s_meta

echo "== Metrics =="
t "Prometheus: no targets DOWN"            prom_no_down
if kubectl get deploy redis -n ibts-apps >/dev/null 2>&1; then
  t "Redis exporter scraped (redis_up=1)"  redis_up
else
  echo "  [SKIP] Redis not deployed in ibts-apps"
fi
t "Container metrics for ibts-apps"        prom_container

echo
echo "Targets not UP:"
curl -s localhost:9090/api/v1/targets | jq -r '.data.activeTargets[]|select(.health!="up")|"  \(.labels.job)  \(.scrapeUrl)"'
echo
[ $FAILED -eq 0 ] && echo "ALL PASS" || echo "FAILURES above -- fix before deploying apps"
